    {

           using var activity =  StartCallActivity("RemoveStoryAlbumStoriesAsync", typeof(RemoveStoryAlbumStories).FullName ?? "RemoveStoryAlbumStoriesAsync");

           try
           {
             return client.RemoveStoryAlbumStoriesAsync(chatId, storyAlbumId, storyIds);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
